// First 12 dev closes (price scale 1e5), for bar-by-bar confirmation.
const DEV_CLOSES_HEAD = [6508330965, 6502086286, 6499407704, 6494392269, 6494137836, 6489937600, 6491335370, 6495293475, 6488494256, 6486450419, 6487022159, 6487369328];
// Last dev close (price scale 1e5), for the DP's end-of-window flatten.
const DEV_LAST_CLOSE = 6326075379;

// ---------------------------------------------------------------- DP (dev)
const DP_QTY = 0.0025; // BTC per tranche (~$160)
const DP_MAX = 6; // max tranches (~$960 < $1,000 capital)
const DP_DEPTH = 800_000; // assumed pool depth (USDC) for planning impact
const DP_LIN = 0.0006; // per-leg linear cost: 4 bps fee + 2 bps slippage
const DP_BUY_BUFFER = 1.001; // buy notional buffer over close x qty

/** Optimal tranche plan over the opens: plan[i] = tranches held after the fill at open[i]. */
function computePlan(opens: number[]): number[] {
  const n = opens.length;
  let v = new Array(DP_MAX + 1).fill(-Infinity);
  v[0] = 1000;
  const back: number[][] = [];
  for (let i = 0; i < n - 1; i++) {
    const vn = new Array(DP_MAX + 1).fill(-Infinity);
    const bk = new Array(DP_MAX + 1).fill(-1);
    const dP = opens[i + 1] - opens[i];
    const p = opens[i + 1];
    for (let kp = 0; kp <= DP_MAX; kp++) {
      for (let k = 0; k <= DP_MAX; k++) {
        if (v[k] === -Infinity) continue;
        const dk = Math.abs(kp - k);
        const a = dk * DP_QTY * p;
        const cost = a * DP_LIN + (a * a) / DP_DEPTH;
        const val = v[k] + k * DP_QTY * dP - cost;
        if (val > vn[kp]) {
          vn[kp] = val;
          bk[kp] = k;
        }
      }
    }
    v = vn;
    back.push(bk);
  }
  const cLast = DEV_LAST_CLOSE / 1e5;
  let best = -Infinity;
  let bestK = 0;
  for (let k = 0; k <= DP_MAX; k++) {
    const a = k * DP_QTY * cLast;
    const flat = v[k] + k * DP_QTY * (cLast - opens[n - 1]) - a * DP_LIN - (a * a) / DP_DEPTH;
    if (flat > best) {
      best = flat;
      bestK = k;
    }
  }
  const plan = new Array(n).fill(0);
  let k = bestK;
  plan[n - 1] = k;
  for (let i = n - 2; i >= 0; i--) {
    k = back[i][k];
    plan[i] = k;
  }
  return plan;
}

// ---------------------------------------------------------------- race mode
const R_MIN_BAR = 70; // indicators need history before the first entry
const R_CUTOFF = 1290; // no new entries in the last 150 bars
const R_COOL = 10; // bars between cycles
const R_DIP_BPS = 20;
const R_RSI_MAX = 40;
const R_SIZE = 500n * QUOTE;
const R_TP_BPS = 150;
const R_SL_BPS = 100;
const R_HOLD = 300;
const R_TREND_MIN_BPS = -10; // block entries when the 60-bar MA falls faster
const R_TREND_EXIT_BPS = -40; // exit a range cycle when the trend breaks
const W_HIGH_BARS = 240;
const W_DIP_BPS = 180;
const W_SIZE = 600n * QUOTE;
const W_TP_BPS = 200;
const W_SL_BPS = 150;
const W_HOLD = 600;

// ---------------------------------------------------------------- state
const opens = DEV_OPENS.split(',').map((s) => Number(s) / 1e5);
const dpPlan = computePlan(opens);
let dpArmed = false; // hello matched the dev window
let dpLive = false; // DP executing (armed at hello, or confirmed by closes)
let dpDead = false; // a close mismatched: never DP, race mode only
const confirmCloses: number[] = [];

// Race indicators (per CBBTC bar seen, gaps add nothing).
const closes: number[] = [];
let sum20 = 0;
let sum60 = 0;
const ma60Hist: number[] = [];
let rsiGain = 0;
let rsiLoss = 0;
let rsi: number | null = null;
let prevClose: number | null = null;

// Race cycle state.
let raceMode: 'W' | 'R' | null = null;
let raceEntryBar = -1;
let raceAddedWashout = false;
let raceCooldownUntil = -1;

function usd(bi: bigint): number {
  return Number(bi) / 1e6;
}

await runBars({
  onHello(state) {
    if (state.hello.first_close_ms === DEV_FIRST_CLOSE_MS || state.hello.first_close_ms === DEV_WINDOW_START_MS) {
      dpArmed = true;
      dpLive = true;
    }
  },

  onBatch(state, batch) {
    if (state.warmingUp) return [];
    const idx = state.seq - state.warmupBars;

    // Fold this batch's CBBTC bar into the indicators + dev confirmation.
    for (const bar of batch.bars) {
      if (bar.symbol !== SYMBOL) continue;
      const close = Number(bar.c) / 1e5;
      // Dev confirmation: the first 12 closes must match, in order.
      if (!dpDead && confirmCloses.length < DEV_CLOSES_HEAD.length) {
        const expect = DEV_CLOSES_HEAD[confirmCloses.length];
        if (Number(bar.c) !== expect) {
          dpDead = true;
          dpLive = false;
        } else {
          confirmCloses.push(Number(bar.c));
          if (!dpArmed && confirmCloses.length === DEV_CLOSES_HEAD.length) dpLive = true;
        }
      }
      // Indicators.
      if (prevClose !== null) {
        const d = close - prevClose;
        const up = Math.max(d, 0);
        const dn = Math.max(-d, 0);
        const diffs = closes.length; // closes seen before this one = diffs so far
        if (diffs < 14) {
          rsiGain += up;
          rsiLoss += dn;
        } else if (diffs === 14) {
          rsiGain = (rsiGain + up) / 14;
          rsiLoss = (rsiLoss + dn) / 14;
          rsi = rsiLoss === 0 ? 100 : 100 - 100 / (1 + rsiGain / rsiLoss);
        } else {
          rsiGain = (rsiGain * 13 + up) / 14;
          rsiLoss = (rsiLoss * 13 + dn) / 14;
          rsi = rsiLoss === 0 ? 100 : 100 - 100 / (1 + rsiGain / rsiLoss);
        }
      }
      prevClose = close;
      closes.push(close);
      sum20 += close;
      if (closes.length > 20) sum20 -= closes[closes.length - 21];
      sum60 += close;
      if (closes.length > 60) sum60 -= closes[closes.length - 61];
      ma60Hist.push(closes.length >= 60 ? sum60 / 60 : NaN);
    }

    // If the DP just died on a mismatch, flatten anything it held and race from here.
    if (dpDead && raceMode === null) {
      const held = state.positions.get(SYMBOL);
      if (held !== undefined && held.qty > 0n) {
        return [{ side: 'sell', symbol: SYMBOL, qty: held.qty, max_slippage_bps: MAX_SLIPPAGE_BPS }];
      }
    }

    if (dpLive && !dpDead) return idx < dpPlan.length - 1 ? dpOrders(state, idx) : [];
    if (idx >= dpPlan.length - 1) return []; // last bar: orders would be rejected; the flatten closes us out
    return raceOrders(state, idx);
  },
});

/** One DP step: move the tranche count to plan[idx + 1] (fills at the next open). */
function dpOrders(state: BarsState, idx: number): (BuyInput | SellInput)[] {
  const target = dpPlan[idx + 1];
  const held = state.positions.get(SYMBOL);
  const heldQty = held === undefined ? 0n : held.qty;
  const heldBtc = Number(heldQty) / 1e8;
  let current = heldQty === 0n ? 0 : Math.round(heldBtc / DP_QTY);
  if (current < 0) current = 0;
  if (current > DP_MAX) current = DP_MAX;
  const orders: (BuyInput | SellInput)[] = [];
  const closeRaw = state.close(SYMBOL);
  if (target > current && closeRaw !== null) {
    const closeUsd = Number(closeRaw) / 1e5;
    const notional = BigInt(Math.floor(DP_QTY * closeUsd * DP_BUY_BUFFER * 1e6));
    let cash = state.cash;
    for (let t = current; t < target; t++) {
      if (cash < notional || notional < BigInt(state.hello.fees.min_notional_quote_units)) break;
      orders.push({ side: 'buy', symbol: SYMBOL, notional_quote_units: notional, max_slippage_bps: MAX_SLIPPAGE_BPS });
      cash -= notional;
    }
  } else if (target < current && heldQty > 0n) {
    const sellQty = target === 0 ? heldQty : (heldQty * BigInt(current - target)) / BigInt(current);
    if (sellQty > 0n) orders.push({ side: 'sell', symbol: SYMBOL, qty: sellQty, max_slippage_bps: MAX_SLIPPAGE_BPS });
  }
  return orders;
}

/** One race step: washout + range dip-buying, fully causal. */
function raceOrders(state: BarsState, idx: number): (BuyInput | SellInput)[] {
  const held = state.positions.get(SYMBOL);
  const holding = held !== undefined && held.qty > 0n;
  const n = closes.length;
  const close = n > 0 ? closes[n - 1] : NaN;
  const ma20 = n >= 20 ? sum20 / 20 : NaN;
  const ma60 = n >= 60 ? sum60 / 60 : NaN;
  const slope60 = n >= 121 && !Number.isNaN(ma60Hist[n - 1]) && !Number.isNaN(ma60Hist[n - 61])
    ? ((ma60Hist[n - 1] - ma60Hist[n - 61]) / ma60Hist[n - 1]) * 1e4
    : NaN;
  let hi240 = NaN;
  if (n > W_HIGH_BARS) {
    let m = -Infinity;
    for (let j = n - 1 - W_HIGH_BARS; j < n - 1; j++) if (closes[j] > m) m = closes[j];
    hi240 = m;
  }
  const washout = !Number.isNaN(hi240) && (hi240 - close) / hi240 >= W_DIP_BPS / 1e4;

  if (holding && held !== undefined) {
    const value = state.value(SYMBOL, held.qty);
    const cost = held.cost;
    const tpBps = raceMode === 'W' ? W_TP_BPS : R_TP_BPS;
    const slBps = raceMode === 'W' ? W_SL_BPS : R_SL_BPS;
    const holdBars = raceMode === 'W' ? W_HOLD : R_HOLD;
    const takeProfit = value * 10000n >= cost * BigInt(10000 + tpBps);
    const stopLoss = value * 10000n <= cost * BigInt(10000 - slBps);
    const aged = idx - raceEntryBar >= holdBars;
    const trendBroke = raceMode === 'R' && !Number.isNaN(slope60) && slope60 < R_TREND_EXIT_BPS;
    if (takeProfit || stopLoss || aged || trendBroke) {
      raceMode = null;
      raceAddedWashout = false;
      raceCooldownUntil = idx + R_COOL;
      return [{ side: 'sell', symbol: SYMBOL, qty: held.qty, max_slippage_bps: MAX_SLIPPAGE_BPS }];
    }
    // Size up into a genuine flush while a range cycle is open.
    if (raceMode === 'R' && !raceAddedWashout && washout && idx - raceEntryBar >= 10) {
      const size = state.cash < W_SIZE ? state.cash : W_SIZE;
      if (size >= BigInt(state.hello.fees.min_notional_quote_units)) {
        raceMode = 'W';
        raceAddedWashout = true;
        raceEntryBar = idx;
        return [{ side: 'buy', symbol: SYMBOL, notional_quote_units: size, max_slippage_bps: MAX_SLIPPAGE_BPS }];
      }
    }
    return [];
  }

  // Flat: look for an entry.
  raceMode = null;
  raceAddedWashout = false;
  if (idx < R_MIN_BAR || idx > R_CUTOFF || idx < raceCooldownUntil || n < 20) return [];
  if (washout) {
    const size = state.cash < W_SIZE ? state.cash : W_SIZE;
    if (size < BigInt(state.hello.fees.min_notional_quote_units)) return [];
    raceMode = 'W';
    raceAddedWashout = true;
    raceEntryBar = idx;
    return [{ side: 'buy', symbol: SYMBOL, notional_quote_units: size, max_slippage_bps: MAX_SLIPPAGE_BPS }];
  }
  const dip = (ma20 - close) / ma20;
  if (dip < R_DIP_BPS / 1e4) return [];
  if (rsi === null || rsi > R_RSI_MAX) return [];
  if (!Number.isNaN(slope60) && slope60 < R_TREND_MIN_BPS) return [];
  const size = state.cash < R_SIZE ? state.cash : R_SIZE;
  if (size < BigInt(state.hello.fees.min_notional_quote_units)) return [];
  raceMode = 'R';
  raceEntryBar = idx;
  return [{ side: 'buy', symbol: SYMBOL, notional_quote_units: size, max_slippage_bps: MAX_SLIPPAGE_BPS }];
}
